import json, sys, re
data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
exps = result['data']['experiments']

def get_sr(m):
    '''Normalize SR to percentage (0-100)'''
    if not m: return None
    for k in ['overall_success_rate', 'overall_sr', 'success_rate', 'avg_sr', 'overall_SR', 'overall_sr_10task']:
        v = m.get(k)
        if v is not None:
            if isinstance(v, str):
                # '19.0% (19/100)' → 19.0
                match = re.match(r'([\d.]+)%', v)
                if match: return float(match.group(1))
                try: v = float(v)
                except: continue
            v = float(v)
            if v <= 1.0: return v * 100  # decimal to pct
            return v
    return None

def get_successes(m):
    if not m: return None
    for k in ['total_successes', 'successes', 'total_success']:
        v = m.get(k)
        if v is not None: return int(v)
    return None

# Compile ALL successful object experiments
print('=== MAGNITUDE CURVE DATA (LIBERO-Object) ===')
print(f'{\"Method\":20s} {\"Norm\":8s} {\"Seed\":6s} {\"SR%\":6s} {\"Succ\":5s} {\"exp_id\"}')
print('-' * 90)

rows = []
for eid, e in exps.items():
    if 'spatial' in eid: continue
    m = e.get('metrics', {}) or {}
    sr = get_sr(m)
    succ = get_successes(m)
    if sr is None: continue

    # Method
    method = 'unknown'
    if 'obs-only' in eid or 'obs_only' in eid or 'obsonly' in eid:
        method = 'obs_only'
    elif 'perdof' in eid:
        method = 'perdof'
    elif 'argmin' in eid:
        method = 'argmin'
    elif 'vla-only' in eid:
        method = 'vla_only'
    elif 'vla-mean' in eid:
        method = 'vla_mean'
    elif 'scalar' in eid:
        method = 'scalar'
    elif 'direct-correction' in eid:
        method = 'direct_corr'
    elif 'reconvla' in eid:
        method = 'reconvla'
    else:
        continue

    # Seed
    seed = None
    for part in eid.replace('_','-').split('-'):
        if part.startswith('seed'):
            try: seed = int(part.replace('seed',''))
            except: pass
    if seed is None and ('v4' in eid or 'v8' in eid or eid.endswith('-object') or 'norm02' == eid.split('-')[-1]):
        seed = 42  # Original experiments were seed 42
    if seed is None and 'object' in eid and not any(x in eid for x in ['seed','v4','v8']):
        seed = 42

    # Norm
    norm = None
    norm_m = m.get('max_correction_norm')
    if norm_m is not None:
        norm = float(norm_m)
    elif 'norm003' in eid or 'norm-0.03' in eid:
        norm = 0.03
    elif 'norm005' in eid or 'norm-0.05' in eid:
        norm = 0.05
    elif 'norm01' in eid or 'norm-0.1' in eid:
        norm = 0.1
    elif 'norm02' in eid or 'norm-0.2' in eid:
        norm = 0.2
    elif 'norm03' in eid or 'norm-0.3' in eid or 'norm0.3' in eid or 'norm0p3' in eid:
        norm = 0.3
    elif 'default' in eid:
        norm = 'default'
    elif method in ('obs_only', 'perdof', 'scalar') and 'v4' in eid:
        norm = 0.1
    elif method in ('argmin', 'vla_only', 'vla_mean', 'direct_corr', 'reconvla'):
        norm = 'N/A'

    rows.append((method, str(norm) if norm else '?', seed or '?', sr, succ or '?', eid))

rows.sort(key=lambda x: (x[0], x[1], str(x[2])))
for r in rows:
    print(f'{r[0]:20s} {r[1]:8s} {str(r[2]):6s} {r[3]:6.1f} {str(r[4]):5s} {r[5]}')
"

